using System.Diagnostics;
using System.Text.RegularExpressions;
using System.Xml.Linq;
using Codalus.Projects.Protocol;
using Codalus.Workbench.Build;
using Codalus.Workbench.Output;
using Codalus.Workbench.Projects;
using Codalus.Workbench.Wcf;
using Codalus.Workbench.Web;

namespace Codalus.Projects.Tests;

/// <summary>
/// WCF (M42, ADR 0066) through the real build host on a copy of samples/Wcf: references generated by the fixture's
/// local dotnet-svcutil (restored here) from its WSDL and from the running CoreWCF service, and the WCF Test Client
/// calling that service on loopback.
/// </summary>
public sealed partial class WcfIntegrationTests : IAsyncLifetime
{
    private const string Ns = "http://codalus.dev/samples/calculator";
    private static readonly TimeSpan s_timeout = TimeSpan.FromMinutes(8);

    private readonly string _root = Path.Combine(Codalus.Platform.RealPath.Resolve(Path.GetTempPath()), "codalus-wcf-" + Guid.NewGuid().ToString("N"));
    private readonly OutputService _output = new();
    private SolutionService _solutions = null!;
    private ServiceReferenceService _references = null!;

    private string Fixture => Path.Combine(_root, "Wcf");

    private string Client => Path.Combine(Fixture, "Client", "Client.csproj");

    private string Service => Path.Combine(Fixture, "Calculator.Service", "Calculator.Service.csproj");

    private static CancellationToken Timeout() =>
        CancellationTokenSource.CreateLinkedTokenSource(TestContext.Current.CancellationToken, new CancellationTokenSource(s_timeout).Token).Token;

    public async ValueTask InitializeAsync()
    {
        Environment.SetEnvironmentVariable("CODALUS_TRASH_DIR", Path.Combine(_root, ".trash"));
        Copy(Path.Combine(BuildHostIntegrationTests.RepoRoot, "samples", "Wcf"), Fixture);
        File.WriteAllText(Path.Combine(_root, "Directory.Build.props"), "<Project />");
        Codalus.Tests.FixtureSdk.Pin(_root);
        File.WriteAllText(Path.Combine(_root, "Directory.Packages.props"), "<Project><PropertyGroup><ManagePackageVersionsCentrally>false</ManagePackageVersionsCentrally></PropertyGroup></Project>");
        _solutions = new SolutionService(() => BuildHostIntegrationTests.HostAssemblyPath);
        _solutions.Log += (_, line) => Console.Error.WriteLine("[host] " + line);
        _references = new ServiceReferenceService(_solutions, _output);
        var solution = await _solutions.OpenAsync(Path.Combine(Fixture, "Wcf.slnx"), trusted: true, restore: false, Timeout());
        await WaitUntilAsync(() => _solutions.Progress is { Completed: true } && _solutions.Projects.Count == solution.Projects.Length);
        var restored = await _solutions.RequestAsync(PackageMethods.ToolCommand, new ToolCommandParams(ToolActions.Restore), PackageJsonContext.Default.ToolCommandParams, PackageJsonContext.Default.ToolCommandResult, Timeout());
        Assert.True(restored.Succeeded, restored.Output);
    }

    public async ValueTask DisposeAsync()
    {
        await _solutions.DisposeAsync();
        try
        {
            Directory.Delete(_root, recursive: true);
        }
        catch (IOException)
        {
        }
        catch (UnauthorizedAccessException)
        {
        }
    }

    [Fact]
    public async Task Wcf_references_are_generated_listed_updated_and_removed()
    {
        var tool = await _references.WcfToolAsync(Client, install: false, Timeout());
        Assert.True(tool.Available, tool.Message);
        Assert.Equal(("8.0.0", "local"), (tool.Version, tool.Source));

        // From the WSDL file, with synchronous operations too: the client, its options in both files, the packages.
        var client = Path.GetDirectoryName(Client)!;
        var wsdl = Path.Combine(Fixture, "contracts", "Calculator.wsdl");
        var added = await _references.AddWcfAsync(new WcfReferenceParams(Client, "Calculator", wsdl, Options: new WcfOptions(WcfOperationKinds.Both)), Timeout());
        var folder = Path.Combine(client, "Connected Services", "Calculator");
        Assert.Equal(folder, added.Folder);
        var code = File.ReadAllText(Path.Combine(folder, "Reference.cs"));
        Assert.Contains("namespace Client.Calculator", code, StringComparison.Ordinal);
        Assert.Contains("class CalculatorServiceClient", code, StringComparison.Ordinal);
        Assert.Contains("AddAsync(int a, int b)", code, StringComparison.Ordinal);
        Assert.Contains("public int Add(int a, int b)", code, StringComparison.Ordinal);
        Assert.Contains("\"ProviderId\": \"Microsoft.VisualStudio.ConnectedService.Wcf\"", File.ReadAllText(Path.Combine(folder, "ConnectedService.json")), StringComparison.Ordinal);
        Assert.True(File.Exists(Path.Combine(folder, "dotnet-svcutil.params.json")));
        Assert.Contains(Client, added.Modified);
        Assert.Contains("System.ServiceModel.Http", File.ReadAllText(Client), StringComparison.Ordinal);
        Assert.Contains("> dotnet svcutil", _references.Channel.GetText(), StringComparison.Ordinal);

        var listed = await _references.ListAsync(Client, Timeout());
        var reference = Assert.Single(listed.References, r => r.Kind == ServiceReferenceKinds.Wcf);
        Assert.Equal(("Calculator", Path.Combine("Connected Services", "Calculator"), "Client.Calculator", wsdl, (string?)null),
            (reference.ClassName, reference.Include, reference.Namespace, reference.Input, reference.SourceUrl));
        Assert.Equal(WcfOperationKinds.Both, reference.Wcf!.Operations);
        Assert.Contains(listed.Packages, p => p.Id == "System.ServiceModel.Http");

        // The generated client compiles, called synchronously from the program.
        File.WriteAllText(Path.Combine(client, "Program.cs"), """
            using var calculator = new Client.Calculator.CalculatorServiceClient(
                new System.ServiceModel.BasicHttpBinding(), new System.ServiceModel.EndpointAddress("http://localhost:5290/CalculatorService.svc"));
            Console.WriteLine(calculator.Add(2, 3));
            """);
        await BuildAsync(Client);

        // New options generate it again: asynchronous operations only, internal types.
        await _references.UpdateWcfAsync(new WcfReferenceParams(Client, "Calculator", Options: reference.Wcf with { Operations = WcfOperationKinds.Async, Internal = true }), Timeout());
        code = File.ReadAllText(Path.Combine(folder, "Reference.cs"));
        Assert.DoesNotContain("public int Add(int a, int b)", code, StringComparison.Ordinal);
        Assert.Contains("internal partial class CalculatorServiceClient", code, StringComparison.Ordinal);
        reference = Assert.Single((await _references.ListAsync(Client, Timeout())).References, r => r.Kind == ServiceReferenceKinds.Wcf);
        Assert.Equal((WcfOperationKinds.Async, true, "Client.Calculator"), (reference.Wcf!.Operations, reference.Wcf.Internal, reference.Namespace));

        // Refresh: the tool's own update from the recorded options.
        await _references.RefreshAsync(Client, reference, Timeout());
        Assert.Contains("internal partial class CalculatorServiceClient", File.ReadAllText(Path.Combine(folder, "Reference.cs")), StringComparison.Ordinal);

        // Mistakes say what's wrong.
        var taken = await Assert.ThrowsAnyAsync<Exception>(() => _references.AddWcfAsync(new WcfReferenceParams(Client, "Calculator", wsdl), Timeout()));
        Assert.Contains("exists already", taken.Message, StringComparison.Ordinal);
        var badName = await Assert.ThrowsAnyAsync<Exception>(() => _references.AddWcfAsync(new WcfReferenceParams(Client, "1 bad", wsdl), Timeout()));
        Assert.Contains("isn't a valid reference name", badName.Message, StringComparison.Ordinal);
        var notWsdl = await Assert.ThrowsAnyAsync<Exception>(() => _references.AddWcfAsync(new WcfReferenceParams(Client, "Broken", Path.Combine(client, "Program.cs")), Timeout()));
        Assert.Contains("dotnet-svcutil failed", notWsdl.Message, StringComparison.Ordinal);

        // Remove: the folder goes to the trash, the packages stay.
        await _references.RemoveAsync(Client, reference, deleteFile: true, Timeout());
        Assert.False(Directory.Exists(folder));
        Assert.DoesNotContain((await _references.ListAsync(Client, Timeout())).References, r => r.Kind == ServiceReferenceKinds.Wcf);
        Assert.Contains("System.ServiceModel.Http", File.ReadAllText(Client), StringComparison.Ordinal);
    }

    [Fact]
    public async Task A_running_corewcf_service_is_referenced_and_called_by_its_address()
    {
        await BuildAsync(Service);
        var dll = Path.Combine(Path.GetDirectoryName(Service)!, "bin", "Debug", "net10.0", "Calculator.Service.dll");
        var start = new ProcessStartInfo("dotnet") { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false };
        start.ArgumentList.Add(dll);
        start.ArgumentList.Add("--urls");
        start.ArgumentList.Add("http://127.0.0.1:0");
        start.Environment["ASPNETCORE_ENVIRONMENT"] = "Development";
        using var service = Process.Start(start)!;
        try
        {
            var listening = new TaskCompletionSource<string>(TaskCreationOptions.RunContinuationsAsynchronously);
            service.OutputDataReceived += (_, e) =>
            {
                if (e.Data is { } line && Listening().Match(line) is { Success: true } match)
                {
                    listening.TrySetResult(match.Groups[1].Value);
                }
            };
            service.BeginOutputReadLine();
            service.BeginErrorReadLine();
            var baseUrl = await listening.Task.WaitAsync(TimeSpan.FromMinutes(1), TestContext.Current.CancellationToken);
            var address = baseUrl + "/CalculatorService.svc";

            // Add Service Reference from the running service's metadata.
            var added = await _references.AddWcfAsync(new WcfReferenceParams(Client, "Live", address + "?wsdl"), Timeout());
            Assert.Contains("class CalculatorServiceClient", File.ReadAllText(Path.Combine(added.Folder, "Reference.cs")), StringComparison.Ordinal);
            var live = Assert.Single((await _references.ListAsync(Client, Timeout())).References, r => r.ClassName == "Live");
            Assert.Equal(address + "?wsdl", live.SourceUrl);

            // The test client: the metadata from the service's address, then each operation.
            using var http = new HttpClient();
            var testClient = new WcfTestClient(http);
            var metadata = await testClient.LoadAsync(address, Timeout());
            var endpoint = Assert.Single(metadata.Endpoints);
            XNamespace ns = Ns;
            string Call(string name, Func<string, string> edit) => edit(WcfTestClient.SampleRequest(endpoint.Operations.Single(o => o.Name == name)));

            var add = await testClient.InvokeAsync(endpoint, endpoint.Operations.Single(o => o.Name == "Add"),
                Call("Add", r => r.Replace("<a>0</a>", "<a>2</a>", StringComparison.Ordinal).Replace("<b>0</b>", "<b>3</b>", StringComparison.Ordinal)), Timeout());
            Assert.False(add.IsFault, add.Body);
            Assert.Equal("5", XElement.Parse(add.Body).Element(ns + "AddResult")!.Value);

            var distance = await testClient.InvokeAsync(endpoint, endpoint.Operations.Single(o => o.Name == "Distance"),
                Call("Distance", r => XElement.Parse(r) is var e && e.Element(ns + "to") is { } to
                    ? Set(e, to, "3", "4")
                    : r), Timeout());
            Assert.Equal("5", XElement.Parse(distance.Body).Element(ns + "DistanceResult")!.Value);

            var greet = await testClient.InvokeAsync(endpoint, endpoint.Operations.Single(o => o.Name == "Greet"),
                Call("Greet", r => r.Replace("<name></name>", "<name>Codalus</name>", StringComparison.Ordinal).Replace("<name />", "<name>Codalus</name>", StringComparison.Ordinal)), Timeout());
            Assert.Equal("Hello, Codalus!", XElement.Parse(greet.Body).Element(ns + "GreetResult")!.Value);

            // A malformed request is the service's fault.
            var fault = await testClient.InvokeAsync(endpoint, endpoint.Operations.Single(o => o.Name == "Add"), Call("Add", r => r.Replace("<a>0</a>", "<a>two</a>", StringComparison.Ordinal)), Timeout());
            Assert.True(fault.IsFault);
        }
        finally
        {
            service.Kill(entireProcessTree: true);
            await service.WaitForExitAsync(CancellationToken.None);
        }
    }

    private static string Set(XElement request, XElement point, string x, string y)
    {
        point.Elements().First(e => e.Name.LocalName == "X").Value = x;
        point.Elements().First(e => e.Name.LocalName == "Y").Value = y;
        return request.ToString();
    }

    [GeneratedRegex(@"Now listening on: (http://127\.0\.0\.1:\d+)")]
    private static partial Regex Listening();

    private async Task BuildAsync(string project)
    {
        var builds = new BuildService(_solutions, _output);
        var result = await builds.BuildAsync(BuildTargets.Build, project, Timeout());
        Assert.True(result.Succeeded, builds.Channel.GetText());
    }

    private static async Task WaitUntilAsync(Func<bool> condition)
    {
        var deadline = DateTime.UtcNow + s_timeout;
        while (!condition())
        {
            Assert.True(DateTime.UtcNow < deadline, "Timed out.");
            await Task.Delay(50, TestContext.Current.CancellationToken);
        }
    }

    private static void Copy(string source, string target)
    {
        Directory.CreateDirectory(target);
        foreach (var file in Directory.EnumerateFiles(source))
        {
            File.Copy(file, Path.Combine(target, Path.GetFileName(file)));
        }

        foreach (var directory in Directory.EnumerateDirectories(source).Where(d => Path.GetFileName(d) is not ("bin" or "obj")))
        {
            Copy(directory, Path.Combine(target, Path.GetFileName(directory)));
        }
    }
}
